// A blank store may be initialized. Preserve foreign, stale, and damaged stores.
bool safe = overlayBits && stage && ops.read(0, 1, stage);
if (safe && persist::checkHeader(stage, pages, seedHash, nullptr)) {
  const auto zeroBlock = [](const uint8_t *block) {
    for (unsigned i = 0; i < persist::kBlock; ++i)
      if (block[i]) return false;
    return true;
  };
  safe = zeroBlock(stage);
  for (uint64_t b = 1; safe && b <= bb; ++b)
    safe = ops.read(b, 1, stage) && zeroBlock(stage);
}
persist::Open result = safe ? overlay.open(ops, pages, seedHash, mode == 1, overlayBits)
                            : persist::Open::Failed;

native_data_persist_gpt_after = native_ufs_store_gpt_check();
if (native_data_persist_gpt || native_data_persist_gpt_after)
  native_data_persist_state = 4;
IOLog("UFS-DATA overlay state=%u header=%u gpt=%u/%u pages=%llu present=%llu\n",
      native_data_persist_state, native_data_persist_header,
      native_data_persist_gpt, native_data_persist_gpt_after,
      pages, overlay.present);
